use super::*;
use crate::{practical::*,rpc::Rpc};use std::path::PathBuf;
const INPUT:&str="試験用の架空の読書会。2026年11月14日 14:00〜16:00、森の図書室、当日受付。日本語の開催案内と運営チェックリストを1つのHTMLにする。";
fn fixture()->(Arc<Engine>,PathBuf,Contract,Value,String){
 let root=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").unwrap()).join(format!("recovery-offline-{}",id()));fs::create_dir_all(&root).unwrap();fs::write(root.join(".ai-guild-qa"),"OFFLINE RECOVERY ONLY").unwrap();
 let e=Engine::open(&root,None).unwrap();let w=workflow();
 let mut j=Job{job_id:id(),workflow_id:w.workflow_id.clone(),nodes:w.nodes.iter().map(|n|(n.node_id.clone(),Run::default())).collect(),workflow:w,status:"running".into(),mode:"real".into(),instruction:INPUT.into(),started_at:now(),ended_at:None,workspace:root.to_string_lossy().into(),thread_id:Some("OFFLINE_RECOVERY_THREAD".into()),turn_id:None,active_node_id:Some("writing".into()),artifacts:vec![],stop_requested:false,pause_requested:false,practical:intake(INPUT).unwrap(),quality:None,recovery:None,collaboration:None};
 j.practical.as_mut().unwrap().turn_starts=2;j.nodes.get_mut("writing").unwrap().status="running".into();j.nodes.get_mut("writing").unwrap().attempt=1;
 e.update(|s|{s.job=Some(j);Ok(())}).unwrap();
 let original=PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().unwrap().join("tests/fixtures/rejected-output");
 let plan=fs::read_to_string(original.join("turn1-original.json")).unwrap();let html=fs::read_to_string(original.join("turn2-original.html")).unwrap();
 let n=e.snapshot().job.unwrap().workflow.nodes[0].clone();e.accept_codex_output(&n,"plan.json",&plan).unwrap();
 e.update(|s|{s.job.as_mut().unwrap().nodes.get_mut("plan").unwrap().status="running".into();Ok(())}).unwrap();e.update(|s|{s.job.as_mut().unwrap().nodes.get_mut("plan").unwrap().status="completed".into();Ok(())}).unwrap();
 let s=e.snapshot();let j=s.job.as_ref().unwrap();let mut bindings=vec![];let mut items=serde_json::Map::new();let mut turns=vec![];
 for(node,raw)in [("plan",plan),("writing",html.clone())]{let turn=format!("OFFLINE_{node}");let request=prompt(&s,j,node).unwrap();bindings.push(Binding{node_id:node.into(),turn_id:turn.clone(),response_sha256:sha(raw.as_bytes()),response_bytes:raw.len() as u64,request_sha256:sha(request.as_bytes())});turns.push(json!({"id":turn,"status":"completed"}));items.insert(turn.clone(),json!({"data":[{"turnId":turn,"item":{"type":"userMessage","content":[{"type":"text","text":request}]}},{"turnId":turn,"item":{"type":"agentMessage","phase":"final_answer","text":raw}}],"nextCursor":null}));}
 let c=Contract{job_id:j.job_id.clone(),thread_id:j.thread_id.clone().unwrap(),turns:bindings};let capture=json!({"thread":{"thread":{"id":c.thread_id,"cwd":root}},"turns":{"data":turns,"nextCursor":null},"items":items});
 fs::write(root.join("proof.json"),serde_json::to_vec(&c).unwrap()).unwrap();fs::write(root.join("offline-recovery-capture.json"),serde_json::to_vec(&capture).unwrap()).unwrap();
 e.update(|s|{let j=s.job.as_mut().unwrap();j.status="failed".into();j.ended_at=Some(now());let run=j.nodes.get_mut("writing").unwrap();run.status="failed".into();run.error=Some("ORIGINAL_FALSE_POSITIVE".into());run.output="PARTIAL_STREAM_MUST_NOT_USE".into();s.event(Some("writing"),"execution_error","failed","ORIGINAL_FALSE_POSITIVE",None,vec![]);Ok(())}).unwrap();
 *e.rpc.lock().unwrap()=Some(Rpc::phase9_fixture(&root).unwrap());(e,root,c,capture,html)
}
fn assert_complete(e:&Engine,root:&Path,c:&Contract){let s=e.snapshot();let j=s.job.as_ref().unwrap();assert_eq!(j.job_id,c.job_id);assert_eq!(j.status,"completed");assert_eq!(j.artifacts.len(),4);assert_eq!(j.practical.as_ref().unwrap().turn_starts,2);assert_eq!(j.nodes["writing"].attempt,1);assert_eq!(j.recovery.as_ref().unwrap().original_failed_run.output,"PARTIAL_STREAM_MUST_NOT_USE");assert_eq!(s.events.iter().filter(|x|x.event_type=="job_completed").count(),1);assert!(s.events.iter().any(|x|x.message=="ORIGINAL_FALSE_POSITIVE"));assert_eq!(sha(&fs::read(root.join("event.html")).unwrap()),c.turns[1].response_sha256);assert!(s.events.iter().all(|x|x.event_type!="turn_dispatch"&&x.event_type!="job_started"));let records=fs::read_to_string(root.join("offline-peer.jsonl")).unwrap();assert!(records.lines().all(|x|{let v:Value=serde_json::from_str(x).unwrap();["thread/read","thread/turns/list","thread/items/list"].contains(&v["method"].as_str().unwrap())}));}
#[test]fn same_job_recovery_readonly_idempotent_restart_and_history(){
 let(e,root,c,_,_)=fixture();let proof=root.join("proof.json").to_string_lossy().to_string();e.recover_formal(proof.clone()).unwrap();assert_complete(&e,&root,&c);let before=fs::read(root.join("offline-peer.jsonl")).unwrap();let events=e.snapshot().events.len();e.recover_formal(proof.clone()).unwrap();assert_eq!(e.snapshot().events.len(),events);assert_eq!(fs::read(root.join("offline-peer.jsonl")).unwrap(),before);assert!(e.control("retry".into()).is_err());e.get_rpc().unwrap().shutdown();drop(e);
 let e=Engine::open(&root,None).unwrap();e.recover_formal(proof).unwrap();assert_complete(&e,&root,&c);let db=e.data.lock().unwrap();assert_eq!(db.store.0.query_row("SELECT count(*) FROM jobs",[],|r|r.get::<_,u64>(0)).unwrap(),1);assert_eq!(db.store.0.query_row("SELECT count(*) FROM artifacts",[],|r|r.get::<_,u64>(0)).unwrap(),4);
}
#[test]fn formal_source_wrong_hash_membership_missing_final_partial_and_request_are_rejected(){
 let(e,root,c,cap,_)=fixture();let s=e.snapshot();verify_capture(&s,&c,&cap).unwrap();
 for mutation in 0..8{let mut bad=cap.clone();match mutation{0=>bad["thread"]["thread"]["id"]=json!("WRONG"),1=>bad["turns"]["data"][1]["id"]=json!("WRONG"),2=>bad["turns"]["data"][1]["status"]=json!("inProgress"),3=>bad["items"]["OFFLINE_writing"]["data"][1]["item"]["phase"]=json!("commentary"),4=>bad["items"]["OFFLINE_writing"]["data"][1]["item"]["text"]=json!("PARTIAL_STREAM_MUST_NOT_USE"),5=>bad["items"]["OFFLINE_writing"]["data"][0]["item"]["content"][0]["text"]=json!("WRONG_REQUEST"),6=>bad["items"]["OFFLINE_writing"]["data"][1]["turnId"]=json!("WRONG"),_=>bad["turns"]["nextCursor"]=json!("MORE")};assert!(verify_capture(&s,&c,&bad).is_err());}
 let mut wrong=c.clone();wrong.job_id="WRONG".into();assert!(verify_capture(&s,&wrong,&cap).is_err());wrong=c.clone();wrong.turns[1].response_sha256="0".repeat(64);assert!(verify_capture(&s,&wrong,&cap).is_err());
 fs::write(root.join("offline-recovery-capture.json"),serde_json::to_vec(&json!({"thread":{},"turns":{},"items":{}})).unwrap()).unwrap();assert!(e.recover_formal(root.join("proof.json").to_string_lossy().into()).is_err());assert_eq!(e.snapshot().job.unwrap().status,"failed");assert!(!root.join("event.html").exists());e.get_rpc().unwrap().shutdown();
}
#[test]fn recovery_crash_checkpoints_adopt_only_exact_durable_files(){
 for stage in 0..4{
  let(e,root,c,cap,html)=fixture();let capture_path=root.join(".recovery/original.json");let bytes=serde_json::to_vec_pretty(&cap).unwrap();install_exact(&capture_path,&bytes).unwrap();
  e.update(|s|{let j=s.job.as_mut().unwrap();j.recovery=Some(Recovery{contract:c.clone(),proof_sha256:sha(&fs::read(root.join("proof.json")).unwrap()),capture_path:capture_path.to_string_lossy().into(),capture_sha256:sha(&bytes),stage:"VERIFIED".into(),started_at:now(),original_failed_run:j.nodes["writing"].clone(),original_failed_at:j.ended_at.clone()});j.status="queued".into();j.nodes.get_mut("writing").unwrap().status="queued".into();Ok(())}).unwrap();
  install_exact(&root.join("event.html"),html.as_bytes()).unwrap(); // crash before file registration
  if stage>=1{
   e.update(|s|{let j=s.job.as_mut().unwrap();j.status="running".into();j.nodes.get_mut("writing").unwrap().status="running".into();Ok(())}).unwrap();let n=e.snapshot().job.unwrap().workflow.nodes[1].clone();e.accept_codex_output(&n,"event.html",&html).unwrap();e.update(|s|{let j=s.job.as_mut().unwrap();j.nodes.get_mut("writing").unwrap().status="completed".into();j.nodes.get_mut("qa").unwrap().status="running".into();j.nodes.get_mut("qa").unwrap().attempt=1;Ok(())}).unwrap();let q=verify_product(e.snapshot().job.as_ref().unwrap()).unwrap();install_exact(&root.join("quality.json"),&serde_json::to_vec_pretty(&q).unwrap()).unwrap();
  }
  if stage>=2{let n=e.snapshot().job.unwrap().workflow.nodes[2].clone();e.quality_node(&n).unwrap();e.update(|s|{let j=s.job.as_mut().unwrap();j.nodes.get_mut("qa").unwrap().status="completed".into();j.nodes.get_mut("delivery").unwrap().status="running".into();j.nodes.get_mut("delivery").unwrap().attempt=1;Ok(())}).unwrap();let j=e.snapshot().job.unwrap();let value=json!({"jobId":j.job_id,"mode":j.mode,"createdAt":now(),"publication":"NOT_PERFORMED","artifacts":j.artifacts});install_exact(&root.join("manifest.json"),&serde_json::to_vec_pretty(&value).unwrap()).unwrap();}
  if stage>=3{let n=e.snapshot().job.unwrap().workflow.nodes[3].clone();e.save_manifest(&n).unwrap();e.update(|s|{s.job.as_mut().unwrap().nodes.get_mut("delivery").unwrap().status="completed".into();Ok(())}).unwrap();}
  e.get_rpc().unwrap().shutdown();drop(e);let e=Engine::open(&root,None).unwrap();*e.rpc.lock().unwrap()=Some(Rpc::phase9_fixture(&root).unwrap());e.recover_formal(root.join("proof.json").to_string_lossy().into()).unwrap();assert_complete(&e,&root,&c);e.get_rpc().unwrap().shutdown();
 }
 let(e,root,_,_,_)=fixture();install_exact(&root.join("event.html"),b"MISMATCH").unwrap();assert!(e.recover_formal(root.join("proof.json").to_string_lossy().into()).is_err());assert_eq!(fs::read(root.join("event.html")).unwrap(),b"MISMATCH");assert_eq!(e.snapshot().job.unwrap().artifacts.len(),1);e.get_rpc().unwrap().shutdown();
}
